(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["eo"] = {"ui":{"skip":"Salti al la enhavo","back":"← Reen al AI-gile","lang.button":"Lingvo: {name}","lang.dialog":"Elektu lingvon","lang.search":"Serĉi lingvojn","lang.none":"Neniu lingvo kongruas","lang.notYet":"{name} ankoraŭ ne estas tradukita","theme.aria":"Ŝanĝi inter hela kaj malhela etoso","theme.toLight":"Ŝanĝi al hela etoso","theme.toDark":"Ŝanĝi al malhela etoso","index.title":"AI-gile: via AI-programista teamo, sur unu tabulo","index.description":"AI-gile estas kanban-tabulo por teamoj de AI-programado. Ili laboras dum vi dormas; vi ricevas unu mallongan stakon da aferoj por decidi, testi kaj akcepti.","hero.logoAlt":"Piktogramo de la tabulo AI-gile","hero.h1.html":"Via AI-programista teamo, sur unu&nbsp;tabulo.","hero.alpha":"🐣 Fermita antaŭ-alfao","hero.alphaTitle":"Frua kaj nefinita: dankon pro la provo!","hero.lede":"Ili konstruas dum vi dormas. Vi vekiĝas al unu mallonga stako: kelkaj demandoj, kelkaj aferoj por testi, unu aŭ du purpuraj rombetoj. Alklaku, akceptu, reen al via kafo.","dl.windows":"Apo por Vindozo","dl.browser":"Uzu ĝin en la retumilo","dl.soon":"Baldaŭ","dl.notify":"🔔 Sciigu min kiam ĝi malfermiĝos","dl.notifySmall":"Alfao aŭ beto","hero.secondary":"Facilmova, sed la teamo neniam bezonas stand-up-kafon. (Stand-up-ojn ili tamen faras.)","pitch.h2":"AI-gile en tiom da vortoj, kiom vi volas","pitch.lede":"Elektu longon, de unu vorto ĝis 144. Ĉiu longo estas propra priskribo, verkita por tiu grandeco. Trenu la ŝovilon aŭ uzu la sagoklavojn.","pitch.rangeLabel":"Longo en vortoj","pitch.dice":"🎲 alia versio","pitch.words.one":"{n} vorto","pitch.words.other":"{n} vortoj","pitch.letters.one":"{n} litero","pitch.letters.other":"{n} literoj","pitch.chars.one":"{n} signo","pitch.chars.other":"{n} signoj","count.line.html.one":"{n} karto nun sur la tabulo","count.line.html.other":"{n} kartoj nun sur la tabulo","features.aria":"Kion ĝi faras","f.pile.h":"Unu stako por vi","f.pile.html":"<b>Por vi</b> kolektas ĉion, kio atendas vin, tra ĉiuj projektoj: demandoj, aferoj por testi, taskoj kiujn povas fari nur homo. Via vico diras, kio venas poste kaj kiom longe ĝi daŭras.","f.sleep.h":"Teamoj, kiuj laboras dum vi dormas","f.sleep.p":"Ĉiu projekto havas teamestron kaj teamon de AI-agentoj. Komentu karton kaj la teamo vekiĝas, faras la laboron kaj redonas ĝin kun paŝoj, kiujn laca homo povas sekvi.","f.tester.h":"AI-testanto kontrolas unue","f.tester.p":"Antaŭ ol io atingas vin, testanto sekvas la paŝojn en kopio de la apo kaj montras, kion ĝi vidis, kun ekrankopio. Foliumu la sukcesintajn kaj akceptu per unu klako.","f.proof.h":"Pruvoj, ne promesoj","f.proof.p":"Ĉiu transdono montras, kio ŝanĝiĝis: la dosierojn, la diferencon, la ekrankopiojn. Ne necesas malfermi ĉiun apon por vidi ĉu ĝi pretas.","f.chat.h":"Babilu kun viaj teamestroj","f.chat.p":"Flanka stango en la stilo de Discord: unu piktogramo por projekto, purpuraj rombetoj por tio, kio bezonas vin. Skribu ideon al teamestro; li faras el ĝi kartojn kaj planon, kun butono ✅ Ek.","f.tidy.h":"Ordigas sin mem","f.tidy.p":"Rilataj kartoj kuniĝas, konfuzaj titoloj riparas, kaj kontrolo de ĵetonoj tenas la kodon svelta. Malpli da aferoj inter kiuj ŝanĝi, malpli por pensi.","f.private.h":"Via, en via komputilo","f.private.li1":"La tabulo funkcias en via propra maŝino kaj respondas nur al vi.","f.private.li2":"Privataj mesaĝoj inter homoj estas tutvoje ĉifritaj.","f.private.li3":"Neniuj kontoj, neniuj spuriloj, neniuj kuketoj.","f.lang.h":"En via lingvo","f.lang.p":"Pli ol 120 lingvoj, de la nederlanda, kimra kaj japana ĝis la pirata, Yoda kaj klingona, kun rapida reveno al la angla por la programistaj vortoj.","tl.aria":"Templinio de la unua konversacio ĝis la vojmapo","tl.h2":"De la unua babilo ĝis tio, kio venas","tl.lede":"Veraj datoj kaj horoj, en via propra horzono. Post hodiaŭ temas pri la plano, sen promesitaj datoj.","tl.today":"Hodiaŭ","tl.planned":"planita","tl.cards.one":"{n} karto","tl.cards.other":"{n} kartoj","join.h2":"Aliĝu","join.lede":"AI-gile estas konstruata de eta homo kaj granda nombro da pacientaj agentoj. Nuntempe ĝi estas privata, en fermita alfao kun amikoj. Ĉu vi volas provi, kiam ĝi malfermiĝos?","join.btn":"Registri intereson","join.small":"Ni skribos al vi retpoŝte, nenion plian","footer.tag":"AI-gile. Neniuj spuriloj, neniuj kuketoj, neniu stand-up-kafo.","footer.licence":"Entreprena licenco","footer.status":"Stato","form.sending":"Sendado…","form.failed":"Tio ne funkciis: reprovu poste.","form.offline":"Ne eblis atingi AI-gile: reprovu poste.","interest.title":"AI-gile: sciigu min kiam la alfao malfermiĝos","interest.description":"Lasu vian retpoŝton por scii, kiam la fermita alfao aŭ beto de AI-gile malfermiĝos.","interest.h1":"🔔 Sciigu min kiam ĝi malfermiĝos","interest.lede":"AI-gile estas en fermita antaŭ-alfao. Lasu vian retpoŝton kaj ni skribos unu fojon, kiam estos loko por vi.","interest.email":"Via retpoŝto","interest.which":"Kiu testo?","interest.alpha":"Fermita alfao: frua, malglata, multaj ŝanĝoj","interest.beta":"Beto: pli stabila, pli malfrue","interest.both":"Ambaŭ, kiu ajn venos unue","interest.submit":"Metu min en la liston","interest.thanks":"Dankon! Vi estas en la listo.","interest.kept":"Konservatas nur via retpoŝto kaj la elektita testo, nur por ĉi tiu listo. Neniu informletero, neniuj spuriloj.","licence.title":"AI-gile: entreprena licenco","licence.description":"Ĉu vi uzas AI-gile en via entrepreno? Petu senpagan entreprenan licencon.","licence.h1":"📜 Entreprena licenco","licence.lede":"Ĉu vi uzas AI-gile en la laboro? Diru al ni, kiu vi estas kaj kion vi faras. Se ĝi faras iom da bono, la licenco estas senpaga.","licence.company":"Firmao","licence.website":"Retejo","licence.what":"Kion vi faras","licence.how":"Kiel ĝi helpas la mondon","licence.email":"Retpoŝto","licence.submit":"Peti","licence.thanks":"Dankon! Ni respondos retpoŝte.","status.title":"Stato de AI-gile","status.h1":"Stato de AI-gile","status.quiet":"Ĉio trankvilas","status.checking":"Kontrolado…","status.offline":"Nun ne eblas atingi la stato-servon (reprovas)","status.updated":"ĝisdatigita {ago}","status.justNow":"ĵus","status.min":"antaŭ {n} min","status.hours":"antaŭ {n} h","status.days":"antaŭ {n} t","live.h2":"Rigardu ĝin konstruiĝi, rekte","live.caption":"Ĉiu karto estas kaŝita: vi vidas la formon de la laboro, ne la vortojn.","live.watching.one":"rekte: {n} rigardas","live.watching.other":"rekte: {n} rigardas","live.offline":"La viva tabulo iom ripozas. Revenu baldaŭ.","live.cols":"Backlog|Farotaj|Farata|Teamo kontrolas|Por ke vi testu|Por la teamo|Farite","live.last.now":"Lasta karto movita ĵus","live.last.min.one":"Lasta karto movita antaŭ {n} min","live.last.min.other":"Lasta karto movita antaŭ {n} min","live.last.hour.one":"Lasta karto movita antaŭ {n} horo","live.last.hour.other":"Lasta karto movita antaŭ {n} horoj","live.last.day.one":"Lasta karto movita antaŭ {n} tago","live.last.day.other":"Lasta karto movita antaŭ {n} tagoj"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotoj.","Delegite."]},{"n":2,"texts":["Robota kanban.","Agentoj, ordigitaj.","Ideoj, konstruitaj."]},{"n":3,"texts":["Kanban por robotoj.","Ideoj fariĝas funkcioj.","Senpaga agenta kanban."]},{"n":5,"texts":["Kanban-tabulo gvidata de agentoj.","Vi skribas kartojn. Agentoj konstruas.","Senpaga, loka, testita, iom malsaĝa."]},{"n":8,"texts":["Senpaga kanban-tabulo, kie AI-agentoj faras la laboron.","Skribu ideon. Agentoj konstruas ĝin. Vi akceptas.","Facilmova por unu homo kaj multaj pacientaj robotoj."]},{"n":13,"texts":["Kanban-tabulo en via komputilo, kie AI-agentoj prenas la kartojn kaj plenumas ilin.","Skribu ideon. Teamo de agentoj konstruas ĝin. Testanto kontrolas. Vi diras jes.","Senpaga, sen kontoj, sen spuriloj: tabulo, kelkaj robotoj, kaj vi gvidas."]},{"n":21,"texts":["AI-gile estas kanban-tabulo por labori kun AI-programaj agentoj. Ili prenas la kartojn; vi testas kaj akceptas ilin.","Ĉiu projekto ricevas teamestron kaj teamon de AI-agentoj. Komentu ajnan karton kaj la teamo tuj ekklopodas por vi.","Senpaga persona tasktabulo, kiu funkcias en via propra komputilo. La laboristoj estas robotoj. Tiu, kiu diras jes, estas vi."]},{"n":34,"texts":["Vi metas ideojn sur tabulon. Teamo de AI-agentoj igas ilin funkciantaj ecoj, testas ilin kaj redonas ilin al vi kun paŝoj por provi. Nenio validas kiel farita, ĝis vi mem tion diras.","AI-gile estas hejmfarita kanban-tabulo, kiun Rich konstruis kun multe da helpo de la agentoj, kiujn ĝi nun administras. Ĝi estas senpaga, funkcias en via komputilo kaj estas kunhavigata kun amikoj, ne vendata.","Imagu ordinaran kanban-tabulon, kun kolumnoj de Backlog ĝis Farite, sed la kartojn prenas AI-agentoj. Ili raportas progreson, demandas kiam ili blokiĝas, kaj ĉiam atendas vian aprobon antaŭ ol io finiĝas."]},{"n":55,"texts":["AI-gile estas kanban-tabulo, kies teamo konsistas el AI-agentoj. Ĉiu projekto havas teamestron, kiu planas la laboron, kaj helpantojn, kiuj konstruas ĝin. Kiam eco pretas, AI-testanto provas ĝin kaj faras ekrankopion, poste ĝi alvenas en vian stakon. Akceptu ĝin, aŭ komentu kaj ili refaras ĝin.","Ĝi komenciĝis kiel maniero de unu homo kontroli multajn sesiojn de AI-programado samtempe, kaj kreskis en veran tabulon. Ĝi funkcias en via maŝino, postulas neniun konton kaj havas neniujn spurilojn. Ĝi estas senpaga por amikoj kaj scivolemuloj. Ĝi ankaŭ estas nefinita, do atendu malglataĵojn kaj foje surprizon.","Jen la honesta versio. Vi ankoraŭ devas havi la ideojn, kaj vi ankoraŭ devas kontroli la rezultojn. Kion AI-gile faras, estas ĉio inter ili: ĝi tenas la kartojn en ordo, vekas la ĝustan agenton kiam vi komentas, montras precize kio ŝanĝiĝis, kaj metas ĉion en unu mallongan stakon por vi."]},{"n":89,"texts":["AI-gile estas senpaga kanban-tabulo, kiun vi funkciigas en via propra komputilo. Anstataŭ homoj, ĉiu projekto havas teamon de AI-agentoj: teamestron, kiu igas viajn ideojn kartoj kaj plano, kaj helpantojn, kiuj prenas la kartojn laŭ prioritato. Kiam io estas konstruita, AI-testanto sekvas la testpaŝojn kaj montras al vi, kion ĝi vidis. Poste ĝi atendas en unu stako nomata Por vi. Vi akceptas ĝin, aŭ vi komentas kaj la teamo provas denove. Nenio iam atingas Farite sen vi.","Kelkaj aferoj, kiujn vi eble ne atendas. Nokta gardo tenas la kolumnon Farotaj plena dum vi dormas, elektante kartojn, kiuj ne bezonas respondon de vi. Ĵetona kalkulilo montras, kiom la agentoj uzis hodiaŭ kaj ĉi-semajne, kaj Senĵetona Reĝimo diras al ili ĉesi elspezi. Vi povas mesaĝi al amikoj, kaj privataj mesaĝoj estas tutvoje ĉifritaj. La tabulo parolas ĉirkaŭ 120 lingvojn, inkluzive de la nederlanda, flandra, pirata kaj klingona. Nenio el ĝi kostas eĉ centon, kaj neniu provas vendi ĝin al vi.","AI-gile estas eta persona projekto, ne kompanio. Rich volis prizorgi plurajn AI-programajn projektojn sen malfermi ĉiun apon por kontroli ilin, do li kaj la agentoj konstruis tabulon por tio, kaj poste uzis la tabulon por konstrui la reston de si mem. Ĝi estas en fermita antaŭ-alfao, kio signifas, ke ĝi funkcias, plejparte, por manpleno da amikoj. Ne ekzistas prezpaĝo, informletero nek kreskoplano. Se ĝi sonas utila, vi povas peti provi ĝin, kiam ĝi malfermiĝos iom pli."]},{"n":144,"texts":["AI-gile estas kanban-tabulo por unu homo kaj multaj AI-agentoj. Ĝi funkcias en via propra komputilo kaj estas tute senpaga. Vi aldonas projektojn, kaj ĉiu projekto ricevas teamestron kaj malgrandan teamon. Vi babilas kun la teamestro, iom kiel en Discord, kaj priskribas ideon; la teamestro igas ĝin kartoj kaj plano, kaj atendas ĝis vi premos Ek. La teamo laboras tra la kartoj laŭ prioritato, per simpla komandlinio farita por lingvomodeloj. Antaŭ ol io revenas al vi, AI-testanto sekvas la paŝojn en kopio de la apo kaj aldonas ekrankopion. Finita laboro alvenas en vian stakon kun la ŝanĝitaj dosieroj kaj la diferenco. Vi akceptas ĝin, aŭ vi lasas komenton kaj la teamo vekiĝas kaj provas denove. Nur vi povas movi karton al Farite.","Tago kun AI-gile, proksimume. Vespere vi lasas kelkajn komentojn: ĉi tiu butono estas en la malĝusta loko, tiu listo devus esti ordigita, ĉu ni povus havi malhelan reĝimon. Vi iras enlitiĝi. La agentoj legas la komentojn, faras la ŝanĝojn, testas ilin kaj redonas ilin al vi. Se Farotaj malplenas, la nokta gardo replenigas ĝin el la backlog per kartoj, kiuj ne bezonas respondon de vi. Matene estas unu mallonga stako: kelkaj demandoj kaj kelkaj aferoj por provi, ĉiu kun paŝoj, kiujn dormema homo povas sekvi, kaj ekrankopio de ĝia funkciado. Vi klakas tra ili, akceptas la bonajn kaj resendas la reston. Ĵetona kalkulilo montras, kion ĉio uzis, kaj Senĵetona Reĝimo ekzistas por maldikaj semajnoj. Poste vi matenmanĝas, en kio la agentoj ankoraŭ ne povas helpi.","Unue, kio AI-gile ne estas. Ĝi ne estas noventrepreno, ĝi ne estas vendata, kaj neniu kolektas viajn datumojn. Ĝi estas senpaga tabulo, kiu funkcias en via komputilo, sen kontoj, sen spuriloj kaj sen kuketoj. Kio ĝi estas: unu ordigita loko por vidi ĉiujn AI-programajn projektojn samtempe, kun teamo de agentoj, kiu plenumas la kartojn, kaj vi, kiu decidas. Ĝi kunigas rilatajn kartojn, riparas konfuzajn titolojn kaj gardas, kiom svelta la kodo restas. Ĝi parolas ĉirkaŭ 120 lingvojn, de la nederlanda kaj flandra ĝis la pirata kaj klingona. Amikoj povas mesaĝi unu al la alia, private kaj ĉifrite. Ĝin konstruis Rich kaj granda nombro da pacientaj agentoj, plejparte uzante sin mem. Ĝi estas en fermita antaŭ-alfao, do en kelkaj lokoj ĝi estas malglata. Se ĝi sonas amuza, petu afable kaj vi eble eniros frue."]}],"quips":{"1":"Unu vorto. Kuraĝa. Eble tro kuraĝa.","3":"Tri vortoj. Jam pli honesta ol la plej multaj produktaj paĝoj.","8":"Ok vortoj. Ankoraŭ pli mallonga ol stand-up.","21":"La longoj, cetere, estas rakontopunktoj. Kompreneble ili estas.","55":"Kvindek kvin vortoj. Du kartoj finiĝis dum vi legis tion.","144":"Tio estis la longa. Ne ekzistas 233. La agentoj enlitiĝis."}},"timeline":{"first-idea.name":"La unua ideo","first-idea.line":"La plej unua konversacio, antaŭ ol ekzistis kodo.","first-board.name":"Unua tabulo","first-board.line":"Tabulo, kiu sekvas sian propran konstruon: kartoj, kolumnoj, treni kaj lasi, projektoj.","team-roles.name":"Teamo kaj roloj","team-roles.line":"Profiloj de agentoj, teamaj ŝablonoj, spacoj kaj kiu faras kion.","install.name":"Instalado kaj eldonoj","install.line":"Zip-dosiero, kiun amiko povas instali, memĝisdatigo, kanaloj kaj reveno.","usage-saver.name":"Ŝparado de uzado","usage-saver.line":"Mezuri kion kostas la rulado, teni la kodon svelta, ŝpari vian limon.","friends.name":"Amikoj kaj kunhavigo","friends.line":"Privataj mesaĝoj, miksita relajso, invitoj, roloj kaj komunaj projektoj.","languages.name":"Lingvoj","languages.line":"Ĉiuj ekrantekstoj en lingva dosiero, unue la nederlanda kaj la flandra.","ai-tester.name":"AI-testanto","ai-tester.line":"Testanto kontrolas ĉiun transdonon unue kaj montras, kion ĝi vidis.","website.name":"La retejo","website.line":"aigile.lol, la antaŭmontro kaj ĉi tiu templinio.","streaming.name":"Babilo kaj elsendado","streaming.line":"Discord, Twitch, OBS, elsendista reĝimo, GIF-oj kaj emoĝioj.","no-ai.name":"Eldono sen AI","no-ai.line":"Tabulo por homoj, kiuj programas sen AI, kaj publikaj tabuloj.","night-watch.name":"Nokta gardo","night-watch.line":"Gardisto kaj Scrum-Mastro tenas la teamojn ĉe la tasko dum vi dormas.","p-more.name":"Ĉio alia","p-more.line":"Pli malgrandaj ideoj, kiuj ankoraŭ atendas sian vicon.","p-android.name":"Telefono kaj Android","p-android.line":"Atingi vian tabulon de telefono, poste denaska Android-apo.","p-release.name":"Alfao kaj pli","p-release.line":"Fermita alfao, la viva retejo, poste beto.","p-languages.name":"Pli da lingvoj","p-languages.line":"Pli ol cent lingvoj, kaj trempa reĝimo por lernantoj.","p-engines.name":"Pli da AI-motoroj","p-engines.line":"Elektu Claude, Codex aŭ Gemini por ĉiu agento.","p-pro.name":"Profesia praktiko","p-pro.line":"Riskaj etikedoj, kunfandaj pordegoj, incidentaj kartoj kaj gardbarilo.","p-self.name":"Prizorgi vin","p-self.line":"Laca reĝimo, memprizorgaj rememoriloj kaj 4:20.","p-servers.name":"Serviloj kaj kresko","p-servers.line":"Tutmondaj servilaj agordoj, roloj kaj planado por kresko.","p-livestream.name":"Elsendaj aldonaĵoj","p-livestream.line":"Twitch-babilo, propraj emoĝioj kaj publika viva vido."},"words":{"button":"📖 Programistaj vortoj","h":"📖 Programistaj vortoj klarigitaj","intro":"La vortoj, kiujn programistoj (kaj la AI-teamoj) uzas, en simpla lingvo.","search":"Serĉi vorton…","none":"Neniu vorto kongruas.","close":"Fermi","list":[{"id":"backlog","word":"Nefarita listo","text":"Ideoj kaj laboro ankoraŭ ne planitaj. Nenio tie estas laborata ĝis ĝi moviĝas al Farotaj."},{"id":"sprint","word":"Sprinto","text":"Mallonga laborperiodo (ofte semajno aŭ du) kun interkonsentita aro de kartoj por fini.","also":["sprintoj"]},{"id":"standup","word":"Stariĝa kunveno","text":"Rapida enregistriĝo: kion ĉiu teamano faris, kion li faros poste, kaj kio haltigas lin.","also":["stariĝa kunveno","stariĝaj kunvenoj"]},{"id":"bug","word":"Cimo","text":"Io, kio ne funkcias kiel ĝi devus.","also":["cimoj"]},{"id":"test","word":"Testo","text":"Provi finitan laboron por kontroli, ke ĝi faras tion, kio estis petita, antaŭ ol vi akceptas ĝin.","also":["testoj"],"noTip":1},{"id":"commit","word":"Enmeto","text":"Konservita momentfoto de la kodo, kun mallonga noto pri tio, kio ŝanĝiĝis. Vi ĉiam povas reiri al unu.","also":["enmetoj"]},{"id":"push","word":"Puŝo","text":"Sendi konservitajn momentfotojn (enmetojn) de ĉi tiu komputilo al GitHub, por ke ili estu savkopiitaj kaj komunigitaj."},{"id":"branch","word":"Branĉo","text":"Aparta linio de laboro en la kodo, por ke oni povu fari ŝanĝojn sen tuŝi la ĉefan version.","also":["branĉoj"]},{"id":"merge","word":"Kunfandi","text":"Kuniĝi la ŝanĝojn de branĉo reen en la ĉefan version."},{"id":"repo","word":"Deponejo","text":"La dosierujo de la projekto kun kodo kaj ĝia plena historio de enmetoj, kutime ankaŭ tenata en GitHub.","also":["deponejo"]},{"id":"refactor","word":"Refaktorado","text":"Ordigi la kodon sen ŝanĝi kion ĝi faras: pli malgrandaj dosieroj, pli klaraj nomoj, malpli da ripetado."},{"id":"deploy","word":"Disponigi","text":"Publikigi novan version, ekzemple sur servilo, kie homoj uzas ĝin."},{"id":"kanban","word":"Kanban","text":"Tabulo kun kolumnoj (Farotaj, Farata, Farite) kie kartoj moviĝas de maldekstre dekstren dum la laboro okazas."},{"id":"wip","word":"WIP-limo","text":"Laboro en progreso: la plej multaj kartoj, kiujn kolumno devus teni, por ke la teamo finu aferojn antaŭ ol komenci pliajn.","also":["WIP"]},{"id":"pr","word":"Tira peto","text":"Peti, ke la ŝanĝoj de branĉo estu kontrolitaj kaj kunfanditaj en la ĉefan version.","also":["PR"]},{"id":"hook","word":"Hoko","text":"Eta komando, kiu funkcias memstare en difinita momento, ekz. kiam AI-seanco startas, por ke la teamo aŭdu viajn komentojn.","also":["hokoj"]},{"id":"token","word":"Ĵetono","text":"La unuo, en kiu AI-uzado estas kalkulata: proksimume kelkaj literoj de teksto legitaj aŭ skribitaj. Pli malmultaj ĵetonoj, pli de via plano restas.","also":["ĵetonoj"]},{"id":"agent","word":"Agento","text":"AI, kiu laboras memstare pri tasko: legas la kodon, faras ŝanĝojn, rulas kontrolojn kaj raportas reen.","also":["agentoj"]}]}};
